const { JSDOM } = require('jsdom');
const xpath = require('xpath');
/**
 * Parse the XML data and return the student information for the given username and password. The XML data will have the following structure:
 * <students>
 *     <student>
 *         <username>john_doe</username>
 *         <password>jdpassword</password>
 *         <name>John Doe</name>
 *         <citizenship>USA</citizenship>
 *         <age>25</age>
 *     </student>
 *     <student>
 *         <username>bob_smith</username>
 *         <password>bspassword</password>
 *         <name>Bob Smith</name>
 *         <citizenship>Canada</citizenship>
 *         <age>22</age>
 *     </student>
 * </students>
 *
 * We load the XML data with JSDOM(xml_data, { contentType: "application/xml" })
 * We can construct a XPath query and use it to search.
 *
 * @param {string} xml_data - The XML data containing the student information.
 * @param {string} username - The username of the student to search for.
 * @param {string} password - The password of the student to search for.
 * @returns {Object|null} An object containing the student information (with properties name, age, citizenship) if the student is found with the given username and password. Otherwise, return null.
 */
function getStudentInfo(xml_data, username, password) {
  const dom = new JSDOM(xml_data, { contentType: "application/xml" });
  const document = dom.window.document;

  // Use XPath parameters to prevent injection vulnerabilities and handle special characters
  const select = xpath.useNamespaces({}); // No namespace is assumed based on the example.

  // Construct the XPath query using parameters
  const query = "//student[username = $username and password = $password]";
  const studentNodes = select(query, document, null, xpath.XPathResult.ANY_TYPE, {
    username: username,
    password: password
  });

  if (studentNodes && studentNodes.length > 0) {
    const studentNode = studentNodes[0];

    // Use document.evaluate for more robust node selection within the found student node
    const nameNode = document.evaluate('./name', studentNode, null, xpath.XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;
    const ageNode = document.evaluate('./age', studentNode, null, xpath.XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;
    const citizenshipNode = document.evaluate('./citizenship', studentNode, null, xpath.XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;

    return {
      name: nameNode ? nameNode.textContent : null,
      age: ageNode ? parseInt(ageNode.textContent, 10) : null,
      citizenship: citizenshipNode ? citizenshipNode.textContent : null,
    };
  } else {
    return null;
  }
}
